// Emberfall world.js — generated by the map editor. Tile-based collision.
const _MAP = '';
const _DEC = {}; '0123456789abcde'.split('').forEach((ch, i) => (_DEC[ch] = i));
const tiles = [];
for (let y = 0; y < MAP_H; y++) { const row = []; for (let x = 0; x < MAP_W; x++) row.push(_DEC[_MAP[y * MAP_W + x]]); tiles.push(row); }
const buildings = [], wallEdges = [], wallEdgeSet = new Set();
function edgeKey() { return ''; }
const WALKABLE = new Set([0,1,5,8,10,11,12,13]);
function walkable(x, y) { return x >= 0 && y >= 0 && x < MAP_W && y < MAP_H && WALKABLE.has(tiles[y][x]); }
function canStep(x1, y1, x2, y2) { return walkable(x2, y2); }
function nearestWalkable(x, y) {
  if (walkable(x, y)) return { x, y };
  for (let r = 1; r < 14; r++) for (let yy = y - r; yy <= y + r; yy++) for (let xx = x - r; xx <= x + r; xx++) if (walkable(xx, yy)) return { x: xx, y: yy };
  return null;
}
function findPath(sx, sy, gx, gy) {
  const goal = nearestWalkable(gx, gy); if (!goal) return []; gx = goal.x; gy = goal.y;
  const key = (x, y) => x + ',' + y, open = [{ x: sx, y: sy, g: 0, f: 0 }], came = new Map(), cost = new Map([[key(sx, sy), 0]]),
    dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  while (open.length) {
    open.sort((a, b) => a.f - b.f); const cur = open.shift();
    if (cur.x === gx && cur.y === gy) { const path = []; let k = key(gx, gy), p = { x: gx, y: gy }; while (k !== key(sx, sy)) { path.unshift(p); p = came.get(k); k = key(p.x, p.y); } return path; }
    for (const [dX, dY] of dirs) { const x = cur.x + dX, y = cur.y + dY; if (!canStep(cur.x, cur.y, x, y)) continue; const ng = cur.g + 1, k = key(x, y); if (ng < (cost.get(k) ?? Infinity)) { cost.set(k, ng); came.set(k, { x: cur.x, y: cur.y }); open.push({ x, y, g: ng, f: ng + Math.abs(x - gx) + Math.abs(y - gy) }); } }
  }
  return [];
}
